import React, { ReactNode, useRef } from 'react';

import { Store, createStore } from '../../../../core/store/store.js';
import { MeterBarChartTooltipContext } from '../context/MeterBarChartTooltipContext.js';
import { MeterBarChartTooltipState, initialState } from '../types/state.js';

export const StoreProvider = ({ children }: { children: ReactNode }) => {
  const storeRef = useRef<Store<MeterBarChartTooltipState>>();

  storeRef.current = createStore(initialState);

  return (
    <MeterBarChartTooltipContext.Provider value={storeRef.current}>
      {children}
    </MeterBarChartTooltipContext.Provider>
  );
};
